 using Contoso.Text;

 namespace Contoso.Text.Tests;

 [TestClass]
 public sealed class StringFormatterTests
 {
     private readonly StringFormatter _formatter = new();

     // ── FormatPhoneNumber ──────────────────────────────────────────

     [TestMethod]
     public void FormatPhoneNumber_ValidDigits_ReturnsFormattedNumber()
     {
         var result = _formatter.FormatPhoneNumber("2025551234");

         Assert.AreEqual("(202) 555-1234", result);
     }

     [TestMethod]
     public void FormatPhoneNumber_ValidDigits_StartsWithAreaCodeInParens()
     {
         var result = _formatter.FormatPhoneNumber("3105559876");

         Assert.StartsWith(result, "(310)");
     }

     [TestMethod]
     public void FormatPhoneNumber_ValidDigits_EndsWithLastFourDigits()
     {
         var result = _formatter.FormatPhoneNumber("3105559876");

         Assert.EndsWith(result, "9876");
     }

     [TestMethod]
     public void FormatPhoneNumber_ValidDigits_ContainsDashSeparator()
     {
         var result = _formatter.FormatPhoneNumber("2025551234");

         Assert.Contains(result, "-");
     }

     [TestMethod]
     public void FormatPhoneNumber_NullInput_ThrowsArgumentNullException()
     {
         Assert.ThrowsExactly<ArgumentNullException>(
             () => _formatter.FormatPhoneNumber(null!));
     }

     [TestMethod]
     public void FormatPhoneNumber_WrongLength_ThrowsArgumentException()
     {
         Assert.ThrowsExactly<ArgumentException>(
             () => _formatter.FormatPhoneNumber("12345"));
     }

     // ── BuildGreeting ──────────────────────────────────────────────

     [TestMethod]
     public void BuildGreeting_WithDefaultTitle_ReturnsGreetingWithMr()
     {
         var result = _formatter.BuildGreeting("Smith");

         Assert.AreEqual("Dear Mr. Smith,", result);
     }

     [TestMethod]
     public void BuildGreeting_WithCustomTitle_ReturnsGreetingWithTitle()
     {
         var result = _formatter.BuildGreeting("Johnson", "Dr.");

         Assert.AreEqual("Dear Dr. Johnson,", result);
     }

     [TestMethod]
     public void BuildGreeting_Result_StartsWithDear()
     {
         var result = _formatter.BuildGreeting("Doe");

         Assert.StartsWith(result, "Dear");
     }

     [TestMethod]
     public void BuildGreeting_Result_EndsWithComma()
     {
         var result = _formatter.BuildGreeting("Doe");

         Assert.EndsWith(result, ",");
     }

     [TestMethod]
     public void BuildGreeting_Result_ContainsName()
     {
         var result = _formatter.BuildGreeting("Williams", "Ms.");

         Assert.Contains(result, "Williams");
     }

     [TestMethod]
     public void BuildGreeting_WhitespaceName_ThrowsArgumentException()
     {
         Assert.ThrowsExactly<ArgumentException>(
             () => _formatter.BuildGreeting("   "));
     }

     // ── GenerateSlug ───────────────────────────────────────────────

     [TestMethod]
     public void GenerateSlug_SimpleTitle_ReturnsLowercaseDashed()
     {
         var result = _formatter.GenerateSlug("Hello World");

         Assert.AreEqual("hello-world", result);
     }

     [TestMethod]
     public void GenerateSlug_TitleWithSpecialChars_StripsNonAlphanumeric()
     {
         var result = _formatter.GenerateSlug("C# is Great!!!");

         Assert.AreEqual("c-is-great", result);
     }

     [TestMethod]
     public void GenerateSlug_Result_DoesNotStartWithDash()
     {
         var result = _formatter.GenerateSlug("  --Leading dashes  ");

         Assert.DoesNotStartWith(result, "-");
     }

     [TestMethod]
     public void GenerateSlug_Result_DoesNotEndWithDash()
     {
         var result = _formatter.GenerateSlug("Trailing dashes---");

         Assert.DoesNotEndWith(result, "-");
     }

     [TestMethod]
     public void GenerateSlug_MixedCase_ProducesLowercase()
     {
         var result = _formatter.GenerateSlug("MSTest Is Fun");

         StringAssert.Matches(result, new System.Text.RegularExpressions.Regex("^[a-z0-9-]+$"));
     }

     [TestMethod]
     public void GenerateSlug_WhitespaceInput_ThrowsArgumentException()
     {
         Assert.ThrowsExactly<ArgumentException>(
             () => _formatter.GenerateSlug("   "));
     }

     // ── FormatCurrency ─────────────────────────────────────────────

     [TestMethod]
     public void FormatCurrency_DefaultSymbol_StartsWithDollarSign()
     {
         var result = _formatter.FormatCurrency(9.99m);

         Assert.StartsWith(result, "$");
     }

     [TestMethod]
     public void FormatCurrency_CustomSymbol_StartsWithSymbol()
     {
         var result = _formatter.FormatCurrency(19.99m, "€");

         Assert.StartsWith(result, "€");
     }

     [TestMethod]
     public void FormatCurrency_WholeNumber_EndsWith00()
     {
         var result = _formatter.FormatCurrency(50m);

         Assert.EndsWith(result, ".00");
     }

     [TestMethod]
     public void FormatCurrency_TwoDecimalPlaces_FormatsCorrectly()
     {
         var result = _formatter.FormatCurrency(1234.56m);

         Assert.AreEqual("$1234.56", result);
     }

     [TestMethod]
     public void FormatCurrency_NegativeAmount_ContainsMinusSign()
     {
         var result = _formatter.FormatCurrency(-5.00m);

         Assert.Contains(result, "-");
     }
 }

